WITH recent_order_items AS (SELECT *, ROUND(unit_price, 2) unit_price_rounded FROM order_items WHERE NOT (quantity BETWEEN 5 AND 6 AND product_id IS NOT NULL AND quantity <> 8)), Agg AS (SELECT order_id, ROUND(STDDEV(quantity), 2) stddev_quantity, SUM(unit_price) total_unit_price FROM recent_order_items GROUP BY order_id) SELECT order_id, stddev_quantity, total_unit_price FROM Agg ORDER BY stddev_quantity DESC;
